        if d['flag'] or d['exotic'] and False: pass
        if d['printed']!=d['sci']: nn.append(f"name printed as '{d['printed'].lstrip('*')}'" if d['flag'] or d['paren'] or d['possibly_exotic'] or '“' in d['printed'] else None)
