        special={}
        if raw_name=='Calytrix tetragona':
            special['nl']=('O/r',"fire response code printed 'K;r-m.i.f71w' (narrabeen lagoon) read as majority killed, a small proportion resprouted after moderate intensity fire (m.i.f), 71w")
        for site,code,key in ((LCRN,l,'lcr'),(NLN,nl,'nl')):
            if not code: continue
            if key in special: v,nt=special[key]
            else:
                assert okp.match(code),(raw_name,code)
                v,nt=fr(code)
            sites.append((site,v,nt,key))
        # time fields
        fill={}; tn=[]; notesonly=[]
        def do(ci,col,target_years):
            cell=c[ci]
            if not cell: return
            if '<u>' in cell and ci in (6,7):
                notesonly.append(f"{LAB[ci-5]} {clean(cell)} (underlined in the paper: unclear whether plants grew from seed or resprouted, so no column filled)"); return
            r=parse_time(cell,target_years)
            if r is None: return
            if r[0]=='NOUNIT':
                notesonly.append(f"{LAB[ci-5]} printed '{clean(cell)}': unit not stated, no column filled"); return
            val,u,cn=r
            if col=='secondary_juvenile_period':
                fill[col]=val; fill['time_unit']=UNIT[u]
                if re.search(r'c\\.|\\?',clean(cell)): tn.append(f"{col} printed '{clean(cell)}' (marks c./? removed)")
            else:
                fill[col]=val
                if cn: tn.append(f"{col} {cn}")
                if re.search(r'c\\.|\\?',clean(cell)): tn.append(f"{col} printed '{clean(cell)}' (marks c./? removed)")
        do(6,'time_to_first_flower_production_resprout_repr3a',True)
        do(7,'age_at_first_flower_production_from_seed_repr3',True)
        do(10,'primary_juvenile_period',True)
